CREATE TABLE IF NOT EXISTS nestdutio_projects(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,draft_version VARCHAR(64),published_version VARCHAR(64),created_at VARCHAR(32) NOT NULL,updated_at VARCHAR(32) NOT NULL,KEY nestdutio_owner(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nestdutio_versions(id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64) NOT NULL,artifact LONGTEXT NOT NULL,created_at VARCHAR(32) NOT NULL,KEY nestdutio_version_project(project_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nestdutio_config(id INT PRIMARY KEY,document TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS nestdutio_tasks(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,project_id VARCHAR(64) NOT NULL,request_key VARCHAR(128) NOT NULL,base_version VARCHAR(64),prompt TEXT NOT NULL,state VARCHAR(32) NOT NULL,version_id VARCHAR(64),error_code VARCHAR(100) NOT NULL DEFAULT '',reservation_id VARCHAR(64) NOT NULL DEFAULT '',created_at VARCHAR(32) NOT NULL,updated_at VARCHAR(32) NOT NULL,UNIQUE KEY nestdutio_user_request(user_id,request_key),KEY nestdutio_task_state(state,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
